def mix(a, b, t):
    return tuple(int(round(a[i] * (1 - t) + b[i] * t)) for i in range(3))


def colour_variant(c):
    """S8 Greys = Colour: the bowtie's grey bands recoloured from the palette's own accents."""
    W, w, gg, e, d, K, Y, P, M, L, C, Wp = c
    return [W, mix(Y, W, 0.35), C, L, mix(M, K, 0.35), K, Y, P, M, L, C, Wp]


def hw10(rgb):
    """sRGB 0..255 -> (Y10, U10 = Cr, V10 = Cb), BT.601 legal range, hardware convention."""
    r, gr, b = (c / 255.0 for c in rgb)
    y = 0.299 * r + 0.587 * gr + 0.114 * b
    cb = (b - y) / 1.772
    cr = (r - y) / 1.402
    cl = lambda v: max(0, min(1023, int(round(v))))
    return cl(64 + y * 876), cl(512 + cr * 896), cl(512 + cb * 896)


def band_table():
    out = []
    for i in range(256):
        f = (i + 0.5) / 256.0
        k = 0
        while k + 1 < len(STARTS) and f >= STARTS[k + 1]:
            k += 1
        out.append(k)
    return out


def band_thresholds():
    """smallest index i with band(i) >= k, k = 1 .. 11 (band = count of thresholds <= i)."""
    b = band_table()
    return [min(i for i in range(256) if b[i] >= k) for k in range(1, len(STARTS))]


def col_table():
    out = []
    for greys in (0, 1):
        for _name, c in PALS:
            cc = colour_variant(c) if greys else c
            for band in range(16):
                out.append(hw10(cc[min(band, 11)]))
    return out


def field_banks():
    fe = [0] * 2048
    fo = [0] * 2048
    for r in range(NROW):
        for c in range(NCOL):
            if r % 2 == 0:
                fe[(r // 2) * NCOL + c] = FIELD[r][c]
            else:
                fo[(r // 2) * NCOL + c] = FIELD[r][c]
    return fe, fo


def emit():
    fe, fo = field_banks()
    band = band_table()
    col = col_table()

    def arr(name, typ, vals, bits):
        body = []
        for i in range(0, len(vals), 16):
            body.append("        " + ", ".join('"' + format(v, '0%db' % bits) + '"' for v in vals[i:i + 16]))
        return "    constant %s : %s := (\n%s\n    );" % (name, typ, ",\n".join(body))

    colw = [(y << 20) | (u << 10) | v for (y, u, v) in col]
    consts = [
        arr("C_FE", "t_rom2k8", fe, 8),
        arr("C_FO", "t_rom2k8", fo, 8),
        arr("C_BAND", "t_rom256x4", band, 4),
        arr("C_COL", "t_rom256x30", colw, 30),
        "    constant C_BT : t_bt := (" + ", ".join(str(t) for t in band_thresholds()) + ");",
    ]
    names = ", ".join(p[0] for p in PALS)
    txt = """-- starburst_pkg.vhd -- GENERATED by starburst.py; edit the generator, not this file.
--
-- C_FE / C_FO: the source field (81 x 49 knots over one folded mirror cell,
-- F8 = (F + 0.15) * 200), even rows / odd rows, address (row / 2) * 81 + col.
-- C_BAND: colourizer index -> band (C_BT: the same as 11 thresholds).  C_COL: {greys, palette, band} -> Y & U & V
-- (10 bits each, U = Cr).  Palettes: %s.

library ieee;
use ieee.std_logic_1164.all;

package starburst_pkg is
    type t_rom2k8 is array(0 to 2047) of std_logic_vector(7 downto 0);
    type t_rom256x4 is array(0 to 255) of std_logic_vector(3 downto 0);
    type t_rom256x30 is array(0 to 255) of std_logic_vector(29 downto 0);
    type t_bt is array(1 to 11) of integer;
%s
end package starburst_pkg;
""" % (names, "\n".join(consts))
    with open(os.path.join(HERE, "starburst_pkg.vhd"), "w") as fh:
        fh.write(txt)


if __name__ == "__main__":
    emit()
